pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount within reasonable bounds and actor non-zero
        vm.assume(amount > 0 && amount < 1 ether);
        vm.assume(actor != address(0));
        // exclude the contract itself from being the actor to avoid self-deposits
        vm.assume(actor != address(c));

        // setup: give actor ether and deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // record total credit after deposit
        uint256 totalCredit = amount;

        // actor withdraws all their credit via withdrawAll
        vm.prank(actor);
        c.withdrawAll();

        // invariant: after withdrawal, contract's ETH balance must be at least totalCredit minus the withdrawn amount.
        // Here the correct contract subtracts exactly the user's credit, leaving balance >= 0.
        // The bug subtracts credit+1, so if totalCredit == amount (i.e., only one depositor),
        // balance becomes amount - (amount+1) = -1 (underflow revert) or insufficient balance.
        // We observe the balance after the operation: for the reference, balance >= 0 always;
        // for the mutant, it may underflow/revert, violating the invariant that balance never goes negative.
        uint256 contractBalance = address(c).balance;
        assertTrue(contractBalance >= 0, "invariant broken: contract underflowed");
    }
}

