pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 creditSum;

    function setUp() public {
        c = new C();
        creditSum = 0;
    }

    function testFuzz_property(uint8 n, uint8 m, uint120 amount) public {
        // Restrict to manageable number of operations; amounts >0 so deposits are meaningful
        vm.assume(n > 0 && m > 0);
        vm.assume(amount > 0);
        address user = address(uint160(n));
        address other = address(uint160(m));
        vm.assume(user != other);

        // Perform a sequence of deposits and withdrawals that keeps track of total credit
        vm.deal(user, uint256(amount) * 2);
        vm.deal(other, uint256(amount) * 2);

        // Deposit from user
        vm.prank(user);
        c.deposit{value: uint256(amount)}();
        creditSum += uint256(amount);

        // Deposit from other
        vm.prank(other);
        c.deposit{value: uint256(amount)}();
        creditSum += uint256(amount);

        // Withdraw all from user; credit should go to 0
        uint256 userCreditBefore = c.credit(user);
        vm.prank(user);
        c.withdrawAll();
        creditSum -= userCreditBefore;

        // Withdraw all from other; credit should go to 0
        uint256 otherCreditBefore = c.credit(other);
        vm.prank(other);
        c.withdrawAll();
        creditSum -= otherCreditBefore;

        // The contract's ETH balance must match the sum of all outstanding credit entries
        uint256 computedSum = c.credit(user) + c.credit(other);
        assertTrue(address(c).balance == computedSum);
    }
}

